-- Move each existing projection into one shared core. Human wrappers retain their
-- original signatures/security/grants; Gateway callers receive only allowlisted fields.
do $share$
declare spec record;body text;original text;lang text;returns_type text;gate text;replacement text;wrapper text;
begin
 for spec in select * from (values
 ('factory_mesti_food_processing_control','date,date,uuid,text,text,text','p_date_from date,p_date_to date,p_finished_good_id uuid,p_qc_status text,p_verification_status text,p_search text','p_date_from,p_date_to,p_finished_good_id,p_qc_status,p_verification_status,p_search','factory_mesti_food_processing_control'),
 ('factory_mesti_finished_product_storage_control','date,date,uuid,uuid,uuid,text','p_date_from date,p_date_to date,p_product_family_id uuid,p_packaging_sku_id uuid,p_storage_location_id uuid,p_search text','p_date_from,p_date_to,p_product_family_id,p_packaging_sku_id,p_storage_location_id,p_search','factory_mesti_finished_product_storage_control'),
 ('factory_get_production_operational_pipeline_snapshot','date,boolean','p_operational_date date,p_include_productions boolean','p_operational_date,p_include_productions','factory_job_order_records'),
 ('factory_get_open_job_order_qty_by_sku','','','','factory_job_order_records')
 ) s(name,argtypes,args,params,module_id) loop
  select p.prosrc,pg_get_functiondef(p.oid),l.lanname,pg_get_function_result(p.oid) into strict body,original,lang,returns_type from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure('public.'||spec.name||'('||spec.argtypes||')');
  if spec.name='factory_mesti_food_processing_control' then
   gate:='public.current_user_has_permission(''factory_production.view'')';
   body:=replace(body,'auth.uid() is not null','(auth.uid() is not null or p_gateway_token is not null)');
  elsif spec.name='factory_mesti_finished_product_storage_control' then
   gate:='(public.current_user_has_permission(''factory_mesti_cleaning.view'') or public.current_user_has_permission(''factory_mesti_cleaning.manage''))';
  else gate:='public.current_user_has_permission(''factory_job_orders.view'')';end if;
  if strpos(body,gate)=0 then raise exception 'Canonical read gate drifted: %',spec.name;end if;
  if spec.module_id='factory_job_order_records' then
   replacement:='feedx_integrations.read_permission(p_gateway_token,''factory_job_orders.view'')';
  else
   replacement:='(case when p_gateway_token is null then '||gate||' else feedx_integrations.navigation_has_module(p_gateway_token,'||quote_literal(spec.module_id)||') end)';
  end if;
  body:=replace(body,gate,replacement);
  execute format('create function feedx_integrations.%I(%s%sp_gateway_token text) returns %s language %I stable security invoker set search_path=public,pg_temp as %L',spec.name||'_core',spec.args,case when spec.args='' then '' else ',' end,returns_type,lang,body);
  execute format('revoke all on function feedx_integrations.%I(%s%stext) from public,anon,authenticated',spec.name||'_core',spec.argtypes,case when spec.argtypes='' then '' else ',' end);
  execute format('grant execute on function feedx_integrations.%I(%s%stext) to authenticated',spec.name||'_core',spec.argtypes,case when spec.argtypes='' then '' else ',' end);
  wrapper:='select * from feedx_integrations.'||spec.name||'_core('||spec.params||case when spec.params='' then '' else ',' end||'null)';
  if lang='plpgsql' then wrapper:=case when returns_type='jsonb' then 'begin return ('||wrapper||');end' else 'begin return query '||wrapper||';end' end;end if;
  -- pg_get_functiondef supplies the exact live body delimiter, so no public attributes are lost.
  original:=regexp_replace(original,'AS \$function\$[\s\S]*\$function\$', 'AS $function$'||wrapper||'$function$');
  execute original;
 end loop;
end $share$;

create function feedx_integrations.navigation_extra_rows(p_token text,p_resource text,p_from date,p_to date) returns setof jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare d date;snapshot jsonb;bucket text;row jsonb;
begin
 case p_resource
 when 'production_pipeline' then
  for d in select generate_series(p_from,p_to,interval '1 day')::date loop
   snapshot:=feedx_integrations.factory_get_production_operational_pipeline_snapshot_core(d,false,p_token);
   return next jsonb_build_object('id',d||':summary','label','Production pipeline summary','module','Production Overview','business_date',d,'operational_date',d,'pipeline_bucket','summary',
    'scheduled',snapshot->'summary'->'scheduled','released',snapshot->'summary'->'released','in_progress',snapshot->'summary'->'in_progress','completed_today',snapshot->'summary'->'completed_today','planned_today',snapshot->'summary'->'planned_today','completion_rate',snapshot->'summary'->'completion_rate','output_by_uom',snapshot->'summary'->'output_by_uom');
   foreach bucket in array array['scheduled','released','in_progress','completed_today'] loop
    for row in select value from jsonb_array_elements(snapshot->bucket) loop
     -- Navigation projection discards every nested payload and personal/free-text field.
     return next row||jsonb_build_object('id',d||':'||bucket||':'||(row->>'id'),'label',row->'job_order_no','module','Production Overview','business_date',d,'operational_date',d,'pipeline_bucket',bucket);
    end loop;
   end loop;
  end loop;
 when 'planning_open_orders' then
  snapshot:=feedx_integrations.factory_get_open_job_order_qty_by_sku_core(p_token);
  for row in select value from jsonb_array_elements(snapshot->'aggregates') loop
   return next row||jsonb_build_object('id',row->'packaging_sku_id','label','Current open planned quantity','module','Production Planning','source','current_snapshot');
  end loop;
  return next jsonb_build_object('id','planning:diagnostics','label','Open-order data quality','module','Production Planning','source','current_snapshot','qualifying_job_order_count',snapshot->'diagnostics'->'qualifying_job_order_count','missing_packaging_sku_count',snapshot->'diagnostics'->'missing_packaging_sku_count','invalid_quantity_count',snapshot->'diagnostics'->'invalid_quantity_count');
 when 'product_stock_adjustments' then
  return query select jsonb_build_object('id',a.id,'label','Product stock adjustment allocation','module','Product Stock Check','business_date',c.check_date,'stock_check_item_id',a.stock_check_item_id,'batch_balance_id',a.batch_balance_id,'quantity',a.quantity,'created_at',a.created_at) from public.factory_product_stock_check_batch_adjustments a join public.factory_product_stock_check_items i on i.id=a.stock_check_item_id join public.factory_product_stock_checks c on c.id=i.stock_check_id where c.check_date between p_from and p_to limit 5001;
 when 'raw_stock_allocations' then
  return query select jsonb_build_object('id',a.id,'label','Raw stock adjustment allocation','module','Raw Material Stock Check','business_date',c.check_date,'stock_check_item_id',a.stock_check_item_id,'raw_material_batch_balance_id',a.raw_material_batch_balance_id,'allocated_qty',a.allocated_qty,'created_at',a.created_at) from public.factory_raw_material_stock_check_batch_allocations a join public.factory_raw_material_stock_check_items i on i.id=a.stock_check_item_id join public.factory_raw_material_stock_checks c on c.id=i.stock_check_id where c.check_date between p_from and p_to limit 5001;
 when 'receiving_costs' then
  return query select jsonb_build_object('id',r.id,'label',r.receipt_no,'module','Raw Material Receiving','business_date',r.received_date,'receipt_no',r.receipt_no,'batch_id',r.batch_id,'raw_material_id',r.raw_material_id,'received_qty',r.received_qty,'uom',r.uom,'unit_cost',r.unit_cost,'total_cost',r.total_cost,'received_date',r.received_date) from public.factory_raw_material_receivings r where r.received_date between p_from and p_to limit 5001;
 when 'sop_substeps' then
  return query select jsonb_build_object('id',r.id,'label',r.instruction,'module','Production SOP','sop_step_id',r.sop_step_id,'sequence_no',r.sequence_no,'instruction',r.instruction,'estimated_minutes',r.estimated_minutes) from public.factory_production_sop_sub_steps r limit 5001;
 when 'sop_qc_checks' then
  return query select jsonb_build_object('id',r.id,'label',r.qc_name,'module','Production SOP','sop_step_id',r.sop_step_id,'sequence_no',r.sequence_no,'qc_type',r.qc_type,'qc_name',r.qc_name,'instructions',r.instructions,'is_required',r.is_required,'checklist_template_id',r.checklist_template_id,'qc_template_name',t.name,'qc_result_mode',t.result_mode) from public.factory_production_sop_step_qc_checks r left join public.factory_qc_checklist_templates t on t.id=r.checklist_template_id limit 5001;
 when 'sop_equipment' then
  return query select jsonb_build_object('id','binding:'||md5(r.sop_id::text||':'||r.equipment_id::text),'label','Procedure equipment binding','module','Production SOP','sop_id',r.sop_id,'equipment_id',r.equipment_id) from public.factory_production_sop_equipment r limit 5001;
 when 'raw_material_categories' then
  return query select jsonb_build_object('id',r.id,'label',r.name,'module','Raw Material Inventory','name',r.name,'status',r.status) from public.factory_raw_material_categories r limit 5001;
 when 'product_tags' then
  return query select jsonb_build_object('id',r.product_family_id::text||':'||r.tag_id::text,'label',t.name,'module','Product Recipes','product_family_id',r.product_family_id,'tag_id',r.tag_id,'name',t.name,'status',t.status) from public.factory_product_family_tags r join public.factory_finished_good_tags t on t.id=r.tag_id limit 5001;

 when 'sop_material_bindings' then
  return query select jsonb_build_object('id','binding:'||md5(r.sop_step_id::text||':'||r.raw_material_id::text),'label','Procedure material binding','module','Production SOP','sop_step_id',r.sop_step_id,'raw_material_id',r.raw_material_id) from public.factory_production_sop_step_materials r limit 5001;
 when 'equipment_categories' then
  return query select jsonb_build_object('id',r.id,'label',r.name,'module','Equipment','name',r.name,'category_code',r.category_code,'status',r.status,'sort_order',r.sort_order) from public.factory_equipment_categories r limit 5001;
 when 'finished_good_categories' then
  return query select jsonb_build_object('id',r.id,'label',r.name,'module','Finished Goods','name',r.name,'status',r.status) from public.factory_finished_good_categories r limit 5001;
 when 'production_qc_checkpoints' then
  return query select jsonb_build_object('id',r.id,'label',r.process_name,'module','Production','business_date',case when p.status='completed' then p.end_date else p.production_date end,'production_id',r.production_id,'production_sop_id',r.production_sop_id,'sop_step_id',r.sop_step_id,'step_no',r.step_no,'process_name',r.process_name,'control_point',r.control_point,'qc_status',r.qc_status) from public.factory_production_qc_checkpoints r join public.factory_productions p on p.id=r.production_id where (case when p.status='completed' then p.end_date else p.production_date end) between p_from and p_to limit 5001;
 when 'supplier_material_links' then
  return query select jsonb_build_object('id','binding:'||md5(r.supplier_id::text||':'||r.raw_material_id::text),'label','Supplier material eligibility','module','Suppliers','supplier_id',r.supplier_id,'raw_material_id',r.raw_material_id) from public.factory_supplier_raw_material_links r limit 5001;
 else raise exception using errcode='42501',message='Resource unavailable.';
 end case;
end $$;
revoke all on function feedx_integrations.navigation_extra_rows(text,text,date,date) from public,anon,authenticated;

create function feedx_integrations.navigation_production_compliance(p_token text,p_module text,p_resource text,p_from date,p_to date) returns setof jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare r jsonb;v jsonb;snapshot jsonb;matches jsonb;resolved boolean;
begin
 if p_module='factory_mesti_food_processing_control' then
  for r in select value from jsonb_array_elements(feedx_integrations.factory_mesti_food_processing_control_core(p_from,p_to,null,null,null,null,p_token)) loop
   select exists(select 1 from public.factory_productions p join public.factory_production_sops sop on sop.id=p.production_sop_id and sop.version=p.sop_version where p.id=(r->>'id')::uuid) into resolved;
   if not resolved then r:=r-array['qc_required_count','qc_evidence_count','qc_requirement_status','qc_summary'];end if;
   v:=jsonb_build_object('sop_resolved',resolved,'data_availability',case when resolved then 'available' else 'unavailable' end,'limitation',case when not resolved then 'Pinned SOP version cannot be resolved. QC requirement counts and summary are unavailable; saved lifecycle remains canonical.' else null end)||jsonb_build_object('id','food_processing_control:'||case when p_resource='evidence' then 'context_' else '' end||(r->>'id'),'record_id',r->'id','label','Food processing control','module','food_processing_control','business_date',r->'completion_date','record_status','completed','state_source','canonical_food_processing_control','source_type','production_end','production_id',r->'id','verification_state',r->'verification_status','verification_status',r->'verification_status','verified_at',r->'verified_at');
   v:=v||(select jsonb_object_agg(key,value) from jsonb_each(r) where key=any(array['job_order_id','job_order_no','production_no','batch_no','completion_date','completion_time','start_date','start_time','operational_completion_at','completed_at','actual_output_qty','good_output_qty','uom','expiry_date','qc_status','qc_required_count','qc_evidence_count','qc_requirement_status','qc_summary']));
   if p_resource='evidence' then v:=v||jsonb_build_object('parent_id','food_processing_control:'||(r->>'id'));end if;
   return next v;
  end loop;
  if p_resource='evidence' then return query select row from feedx_integrations.mesti_resource_evidence(p_from,p_to) row where row->>'module'='food_processing_control';end if;
 else
  -- Evaluate the canonical batch projection once; never choose an arbitrary ambiguous batch.
  select coalesce(jsonb_agg(to_jsonb(s)),'[]') into snapshot from feedx_integrations.factory_mesti_finished_product_storage_control_core(p_from,p_to,null,null,null,null,p_token)s;
  for v in select row from feedx_integrations.mesti_resource_occurrences(p_from,p_to) row where row->>'module'='finished_product_storage_control' loop
   select coalesce(jsonb_agg(s),'[]') into matches from jsonb_array_elements(snapshot)s where s->>'production_id'=v->>'production_id';
   r:=matches->0;
   if jsonb_array_length(matches)<>1 then
    return next (v-'record_id')||jsonb_build_object('data_availability','unavailable','limitation','Canonical completed-production batch projection is missing or ambiguous. No quantity, expiry or Location is inferred.');
   else
    v:=v||jsonb_build_object('id','finished_product_storage_control:'||case when p_resource='evidence' then 'batch_'||(r->>'id') else v->>'production_id' end,'state_source','canonical_finished_product_storage_control','data_availability','available');
    v:=v||(select jsonb_object_agg(key,value) from jsonb_each(r) where key=any(array['job_order_id','job_order_no','production_no','completed_at','completion_date','completion_time','finished_good_id','packaging_sku_id','packaging_sku_code','packaging_sku_name','completed_qty','completed_uom','storage_location_id','storage_location_name','batch_no','manufacturing_date','expiry_date']));
    if p_resource='evidence' then v:=v||jsonb_build_object('record_id',r->'id','parent_id','finished_product_storage_control:'||(v->>'production_id'));end if;
    return next v;
   end if;
  end loop;
 end if;
end $$;
revoke all on function feedx_integrations.navigation_production_compliance(text,text,text,date,date) from public,anon,authenticated;

create or replace function feedx_integrations.navigation_source_rows(p_token text,p_module text,p_resource text,p_from date,p_to date) returns setof jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare scope jsonb;v_count integer;
begin
 select b.row_scope into scope from feedx_integrations.navigation_resources b join feedx_integrations.resources r on r.key=b.resource_key where b.module_id=p_module and r.slug=p_resource;
 if p_module in ('factory_mesti_food_processing_control','factory_mesti_finished_product_storage_control') and p_resource in ('occurrences','statuses','evidence') then
  return query select * from feedx_integrations.navigation_production_compliance(p_token,p_module,p_resource,p_from,p_to) limit 5001;
 elsif p_resource in ('production_pipeline','planning_open_orders','product_stock_adjustments','raw_stock_allocations','receiving_costs','sop_substeps','sop_qc_checks','sop_equipment','raw_material_categories','product_tags') then
  return query select * from feedx_integrations.navigation_extra_rows(p_token,p_resource,p_from,p_to) limit 5001;
 elsif p_resource in ('sop_material_bindings','equipment_categories','finished_good_categories','production_qc_checkpoints','supplier_material_links') then
  return query select * from feedx_integrations.navigation_extra_rows(p_token,p_resource,p_from,p_to) limit 5001;
 elsif p_resource='finished_goods' then
  return query select v||jsonb_build_object('category_id',r.category_id,'b2b_price',r.b2b_price) from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to)v join public.factory_finished_goods r on r.id=(v->>'id')::uuid;
 elsif p_resource='equipment' then
  return query select v||jsonb_build_object('category_id',r.category_id) from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to)v join public.factory_equipment r on r.id=(v->>'id')::uuid;
 elsif p_resource='qc_results' then
  return query select v||jsonb_build_object('remarks_present',nullif(btrim(r.remarks),'') is not null) from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to)v join public.factory_production_qc_results r on r.id=(v->>'id')::uuid;
 elsif p_resource='raw_materials' then
  return query select v||jsonb_build_object('manual_unit_cost',r.manual_unit_cost,'manual_cost_uom',r.manual_cost_uom) from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to)v join public.factory_raw_materials r on r.id=(v->>'id')::uuid;
 elsif p_resource='product_stock_counts' then
  return query select v||jsonb_build_object('positive_adjustment_confirmed',r.positive_adjustment_confirmed,'adjustment_storage_location_id',r.adjustment_storage_location_id,'positive_adjustment_batch_balance_id',r.positive_adjustment_batch_balance_id) from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to)v join public.factory_product_stock_check_items r on r.id=(v->>'id')::uuid;
 elsif scope ? 'module' then
  return query select v from feedx_integrations.mesti_resource_rows(p_resource,p_from,p_to)v where v->>'module'=scope->>'module' limit 5001;
 elsif p_resource='audit_trail' then
  return query select v from feedx_integrations.navigation_audit_rows(p_from,p_to)v where feedx_integrations.navigation_has_module(p_token,feedx_integrations.audit_navigation_owner(v->>'action')) limit 5001;
 else return query select * from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to);end if;
 get diagnostics v_count=row_count;
 if v_count>5000 then raise exception using errcode='54000',message='Authorized source window exceeds 5000 records; narrow dates.';end if;
end $$;
revoke all on function feedx_integrations.navigation_source_rows(text,text,text,date,date) from public,anon,authenticated;

-- Discovery advertises executable module operations only; dependencies remain visible as explanations.
create or replace function feedx_integrations.discovery(p_identity uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 with granted as (
 select c.*,r.slug from feedx_integrations.machine_identities m join feedx_integrations.capabilities c on c.adapter_key=m.adapter_key left join feedx_integrations.resources r on r.key=c.resource_key join public.permissions p on p.code=c.permission_code join public.role_permissions rp on rp.role_id=m.role_id and rp.permission_id=p.id where m.id=p_identity and c.implemented and not c.requires_human_approval
 ),allowed as (
 select mcp_tool from granted
 union select 'query_mesti_resources' where exists(select 1 from granted where slug in ('requirements','occurrences','statuses','schedules','evidence'))
 union select tool_id from feedx_integrations.capabilities where navigation_module_id is null and resource_key is null and action_type='read' and exists(select 1 from granted where slug='mesti_review')
 ),operations as (
 select jsonb_build_object('resource',g.slug,'action',op) as value from granted g cross join lateral unnest(case when g.action_type='view' then array['list','read','search','filter'] else array[g.action_type] end)op where g.slug is not null
 union all select jsonb_build_object('resource',r.slug,'action',op,'business_module',g.navigation_module_id) from granted g join feedx_integrations.navigation_resources b on b.module_id=g.navigation_module_id join feedx_integrations.resources r on r.key=b.resource_key cross join unnest(array['list','read','search','filter'])op where not exists(select 1 from jsonb_array_elements_text(b.required_modules) dep where not exists(select 1 from granted source_grant where source_grant.navigation_module_id=dep))
 ),catalog as (
 select jsonb_build_object('resource',r.slug,'label',r.label,'filters',r.filter_fields,'date_semantics',r.date_semantics) as value from feedx_integrations.resources r where exists(select 1 from granted g where g.resource_key=r.key)
 union all select jsonb_build_object('resource',r.slug,'business_module',n.id,'business_label',n.label,'section',n.section,'coverage',n.coverage,'limitation',n.explanation,'row_scope',b.row_scope,'requires_modules',b.required_modules,'query_available',not exists(select 1 from jsonb_array_elements_text(b.required_modules) dep where not exists(select 1 from granted source_grant where source_grant.navigation_module_id=dep)),'missing_required_modules',(select coalesce(jsonb_agg(jsonb_build_object('id',dep,'label',required.label)),'[]') from jsonb_array_elements_text(b.required_modules)dep join feedx_integrations.navigation_modules required on required.id=dep where not exists(select 1 from granted source_grant where source_grant.navigation_module_id=dep)),'fields',(select coalesce(jsonb_agg(f),'[]') from jsonb_array_elements_text(b.allowed_fields)f where not b.relationship_modules ? f or exists(select 1 from granted target where target.navigation_module_id=b.relationship_modules->>f)),'filters',(select coalesce(jsonb_agg(f),'[]') from jsonb_array_elements_text(r.filter_fields)f where b.allowed_fields ? f and (not b.relationship_modules ? f or exists(select 1 from granted target where target.navigation_module_id=b.relationship_modules->>f))),'date_semantics',r.date_semantics) from granted g join feedx_integrations.navigation_modules n on n.id=g.navigation_module_id join feedx_integrations.navigation_resources b on b.module_id=n.id join feedx_integrations.resources r on r.key=b.resource_key
 )
 select jsonb_build_object('authorized',true,'tools',(select coalesce(jsonb_agg(mcp_tool),'[]') from allowed),'resource_catalog',(select coalesce(jsonb_agg(value),'[]') from catalog),'resource_actions',(select coalesce(jsonb_agg(value),'[]') from operations));
$$;

